  "W0_finite_QQ_algebra_JS": "(function makeFiniteQQ(I,modulus){\n const F=I.primitive(modulus)[0],degree=F.length-1;\n if(degree<1)throw Error(\"positive modulus required\");\n function reduce(q){\n  q=q instanceof I.Q?q:new I.Q(q);let a=q.a.slice(),den=q.d;\n  while(a.length>=F.length){const c=a.at(-1),k=a.length-F.length,raw=I.sub(I.scale(a,F.at(-1)),I.shift(I.scale(F,c),k));const norm=new I.Q(raw,den*F.at(-1));a=norm.a;den=norm.d;}\n  return new I.Q(a,den);\n }\n class K{\n  constructor(v=0){this.q=v instanceof K?v.q:reduce(v instanceof I.Q?v:new I.Q(v));}\n  add(v){v=new K(v);return new K(this.q.add(v.q));}\n  neg(){return new K(this.q.neg());}\n  sub(v){return this.add(new K(v).neg());}\n  mul(v){v=new K(v);return new K(this.q.mul(v.q));}\n  scale(c,d=1n){return new K(this.q.scale(BigInt(c),BigInt(d)));}\n  pow(n){let r=new K(1),v=this;while(n){if(n%2)r=r.mul(v);n=Math.floor(n/2);if(n)v=v.mul(v);}return r;}\n  zero(){return this.q.zero();}\n  eq(v){return this.q.eq(new K(v).q);}\n  inverse(){const cert=I.pxgcd(this.q.a,F);if(cert.g.length!==1){const e=new Error(\"NONUNIT_FINITE_QQ\");e.factor=cert.g;e.certificate=cert;throw e;}const inv=new K(cert.u.scale(this.q.d,cert.g[0]));if(!this.mul(inv).eq(1))throw Error(\"finite inverse actual product\");return inv;}\n  div(v){return this.mul(new K(v).inverse());}\n  json(){return this.q.json();}\n }\n return{K,degree,F,reduce};\n})",
