  "W0_H_finite_component_return_JS": "(()=>{\nconst I=eval(load(\"W0_primitive_integer_poly_JS\")),spec=load(\"W0_H_finite_component_request\"),F=spec.modulus.map(BigInt),started=Date.now(),{K}=eval(load(\"W0_finite_QQ_algebra_JS\"))(I,F);\nconst raw=load(\"W0_H_cubic_products_augmented_rows\"),original=raw.map(row=>row.map(p=>new K(I.fromPjson(p)))),A=original.map(row=>row.slice()),n=A.length,trace=A.map((_,i)=>Array.from({length:n},(_,j)=>new K(i===j?1:0))),pivotcols=[],selected=A.map((_,i)=>i);let pos=0,unitCalls=0;\nfunction checkBound(){if(Date.now()-started>60000)throw Error(\"FINITE_ORIGINAL_COMPONENT_60_SECOND_BOUND\");}\nfunction rowIdentity(i){for(let j=0;j<6;j++){let q=new K();for(let h=0;h<n;h++)q=q.add(trace[i][h].mul(original[h][j]));if(!q.eq(A[i][j]))throw Error(\"actual original finite row trace failure\");}}\ntry{\n for(let col=0;col<6;col++){\n  const opts=[];for(let i=pos;i<n;i++)if(!A[i][col].zero())opts.push(i);if(!opts.length)continue;\n  opts.sort((i,j)=>A[i][col].q.deg()-A[j][col].q.deg());const sw=opts[0];[A[pos],A[sw]]=[A[sw],A[pos]];[trace[pos],trace[sw]]=[trace[sw],trace[pos]];[selected[pos],selected[sw]]=[selected[sw],selected[pos]];\n  const inv=A[pos][col].inverse();unitCalls++;A[pos]=A[pos].map(v=>v.mul(inv));trace[pos]=trace[pos].map(v=>v.mul(inv));\n  for(let i=0;i<n;i++)if(i!==pos&&!A[i][col].zero()){const c=A[i][col];A[i]=A[i].map((v,j)=>v.sub(c.mul(A[pos][j])));trace[i]=trace[i].map((v,j)=>v.sub(c.mul(trace[pos][j])));checkBound();}\n  pivotcols.push(col);pos++;checkBound();\n }\n for(let i=0;i<pos;i++)rowIdentity(i);\n const impossible=pivotcols.includes(5);if(impossible){const i=pivotcols.indexOf(5);for(let j=0;j<5;j++)if(!A[i][j].zero())throw Error(\"constant row not isolated\");if(!A[i][5].eq(1))throw Error(\"constant row not one\");}\n const result={stage:\"whole_finite_original_component_return\",label:spec.label,wallSeconds:(Date.now()-started)/1000,degree:F.length-1,rank:pos,pivotcols,unitCalls,actualOriginalRowProductsVerified:true,excludedByConstantRow:impossible};\n store(\"W0_H_finite_component_\"+spec.label,{result,modulus:F.map(String),rows:A.slice(0,pos).map(row=>row.map(v=>v.json())),traces:trace.slice(0,pos).map(row=>row.map(v=>v.json())),selected:selected.slice(0,pos)});\n return result;\n}catch(e){\n if(e.message===\"NONUNIT_FINITE_QQ\"){const G=e.factor,Q=I.divexact(F,G);if(!I.eq(I.mul(G,Q),F))throw Error(\"finite split product failure\");const cert=e.certificate;const result={stage:\"finite_original_pivot_whole_zero_fibre_split\",label:spec.label,wallSeconds:(Date.now()-started)/1000,degree:F.length-1,partialRank:pos,pivotcols,factor:G.map(String),complement:Q.map(String),actualUnivariateBezoutVerified:true,wholeFibreRetained:true,claimExcluded:false};store(\"W0_H_finite_component_\"+spec.label,{result,modulus:F.map(String),split:{left:G.map(String),right:Q.map(String)}});return result;}\n throw e;\n}\n})()",
