const STEPS = ["W0_H_full_affine_build_JS","W0_H_quad_head_matrix_JS","W0_H_paid_quad_and_cubic_overlap_graded_JS","W0_H_finite_six_generator_JS","W0_H_finite_constant_cofactor_JS","W0_H_lowest_original_row_products_JS","W0_H_NS_products_JS","W0_H_PS_products_JS","W0_H_cubic_products_rank_JS","W0_H_original_product_cover_JS","W0_H_complete_factorization_JS","W0_H_prepare_finite_cover_JS","W0_H_finite_component_return_JS","W0_H_select_F26_JS","W0_H_finite_component_return_JS","W0_H_finish_finite_cover_JS"];
function makeRuntime(emit) {
 const data=new Map(Object.entries(SOURCES));
 function load(k) { if(!data.has(k))throw new Error("missing regeneration dependency: "+k);return data.get(k); }
 function store(k,v) {data.set(k,v);}
 function notify(v) {if(emit)emit(v);}
 function run(k) {return eval(load(k));}
 return {load,store,run,data};
}
function main() {
 const runtime=makeRuntime(v=>console.log(JSON.stringify(v)));
 for(const key of STEPS){const r=runtime.run(key);console.log(JSON.stringify({component:key,result:r}));}
 const result=runtime.load("W0_H_complete_finite_exclusion_result");
 if(!result.wholeFiniteHExcluded||result.wholeWZeroExcluded||result.ordinaryISPCompleted)throw new Error("wrong completion scope");
 console.log(JSON.stringify(result));return runtime;
}
if(typeof module!=="undefined"&&module.exports)module.exports={makeRuntime,STEPS,main};
if(typeof require==="undefined"||require.main===module)main();
